// TDV 2215 Terminal Font
// Extracted from TDV2215 specification bitmaps (spec/TDV2115/character_set_*.bmp)
// Character cell: 9x14 dots (7x9 character matrix per TDV2115/2215 spec)
//
// Character Sets:
// - Set 1 (fontNum=0,1): ASCII (0x00-0x7F) with ISO 646 national variants
// - Set 2 (fontNum=2): Line Drawing, histogram, plotting
// - Set 3 (fontNum=3): Subscript/Superscript
// - Set 4 (fontNum=4): Control code display
//
// ISO 646 National Variants (positions 0x5B-0x5E, 0x7B-0x7E):
// - International (0): 0x5B -> [, 0x5C -> \, 0x5D -> ], 0x5E -> ^, 0x7B -> {, 0x7C -> |, 0x7D -> }, 0x7E -> ~
// - Norwegian (1): 0x5B -> Æ, 0x5C -> Ø, 0x5D -> Å, 0x5E -> ^, 0x7B -> æ, 0x7C -> ø, 0x7D -> å, 0x7E -> ¦
// - Swedish (2): 0x5B -> Ä, 0x5C -> Ö, 0x5D -> Å, 0x5E -> ^, 0x7B -> ä, 0x7C -> ö, 0x7D -> å, 0x7E -> ¦
// - German (3): 0x5B -> Ä, 0x5C -> Ö, 0x5D -> Ü, 0x5E -> ¦, 0x7B -> ä, 0x7C -> ö, 0x7D -> ü, 0x7E -> ß
//
// ARCHITECTURE: Each variant stores a COMPLETE 128-character charset array.

namespace RetroTerm.Core.Fonts
{
    public class FontTDV2215 : FontBase
    {
        private ushort[] _activeCharset1;
        private int _characterSetVariant = 0;

        public override int CharacterSetVariant
        {
            get => _characterSetVariant;
            set
            {
                if (value < 0 || value > 3) value = 0;
                if (_characterSetVariant != value)
                {
                    _characterSetVariant = value;
                    _activeCharset1 = value switch
                    {
                        1 => NorwegianCharset1,
                        2 => SwedishCharset1,
                        3 => GermanCharset1,
                        _ => InternationalCharset1
                    };
                }
            }
        }

        public FontTDV2215()
        {
            Height = 14;
            HeightToUse = 14;
            Width = 9;
            stretchY = 1;
            IncludeBlankSpace = true;

            _activeCharset1 = InternationalCharset1;

            fontNumOffset = new ushort[]
            {
                0,      // Set 1: ASCII (fontNum=0)
                0,      // Set 1 duplicate (fontNum=1)
                0,      // Set 2: Line Drawing (fontNum=2) - handled in GetFontBits
                0,      // Set 3: Subscript (fontNum=3) - handled in GetFontBits
                0       // Set 4: Control Display (fontNum=4) - handled in GetFontBits
            };

            glyphs = InternationalCharset1;
        }

        /// <summary>
        /// Returns the bitmap rows for one character from the character set the font number names.
        /// </summary>
        /// <param name="fontValue">
        /// The character's position in the chosen set, which for an ordinary character is its code.
        /// </param>
        /// <param name="fontNum">
        /// Which character set to read - 0 and 1 ASCII, 2 line drawing, 3 subscript, 4 control
        /// code display.
        /// </param>
        /// <returns>
        /// The glyph bit rows, or null when the chosen set has no glyph at that position.
        /// </returns>
        /// <remarks>
        /// This model keeps each character set in its own array rather than at an offset inside one
        /// ROM, which is why <see cref="FontBase.fontNumOffset"/> is all zeroes here and the
        /// selection happens in this method instead. The comment on that table says the same thing
        /// from the other end.
        /// </remarks>
        public override ushort[]? GetFontBits(ushort fontValue, int fontNum)
        {
            ushort[] sourceArray;

            // Select the appropriate charset array based on fontNum
            switch (fontNum)
            {
                case 0:
                case 1:
                    sourceArray = _activeCharset1;
                    break;
                case 2:
                    sourceArray = Charset2LineDrawing;
                    break;
                case 3:
                    sourceArray = Charset3Subscript;
                    break;
                case 4:
                    sourceArray = Charset4ControlDisplay;
                    break;
                default:
                    return null;
            }

            if (fontValue >= 0x80)
                return null;

            int startIndex = fontValue * Height;
            if (startIndex + Height > sourceArray.Length)
                return null;

            ushort[] result = new ushort[Height];
            for (int i = 0; i < Height; i++)
            {
                result[i] = sourceArray[startIndex + i];
            }
            return result;
        }

